1	package org.jsoup.parser;
2	
3	import org.jsoup.helper.Validate;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.nodes.Document;
6	import org.jsoup.nodes.Entities;
7	import org.jspecify.annotations.Nullable;
8	
9	import java.util.Arrays;
10	
11	/**
12	 * Readers the input stream into tokens.
13	 */
14	final class Tokeniser {
15	    static final char replacementChar = '\uFFFD'; // replaces null character
16	    private static final char[] notCharRefCharsSorted = new char[]{'\t', '\n', '\r', '\f', ' ', '<', '&'};
17	
18	    // Some illegal character escapes are parsed by browsers as windows-1252 instead. See issue #1034
19	    // https://html.spec.whatwg.org/multipage/parsing.html#numeric-character-reference-end-state
20	    static final int win1252ExtensionsStart = 0x80;
21	    static final int[] win1252Extensions = new int[] {
22	            // we could build this manually, but Windows-1252 is not a standard java charset so that could break on
23	            // some platforms - this table is verified with a test
24	            0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
25	            0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
26	            0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
27	            0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178,
28	    };
29	
30	    static {
31	        Arrays.sort(notCharRefCharsSorted);
32	    }
33	
34	    private final CharacterReader reader; // html input
35	    private final ParseErrorList errors; // errors found while tokenising
36	    private final TreeBuilder treeBuilder; // current tree state for contextual tokenisation
37	
38	    private TokeniserState state = TokeniserState.Data; // current tokenisation state
39	    @Nullable private Token emitPending = null; // the token we are about to emit on next read
40	    private boolean isEmitPending = false;
41	    private boolean ignoreLeadingLf; // skip one newline immediately after pre, listing, or textarea
42	    final TokenData dataBuffer = new TokenData(); // buffers data looking for </script>
43	
44	    final Document.OutputSettings.Syntax syntax; // html or xml syntax; affects processing of xml declarations vs as bogus comments
45	    final Token.StartTag startPending;
46	    final Token.EndTag endPending;
47	    Token.Tag tagPending; // tag we are building up: start or end pending
48	    final Token.Character charPending = new Token.Character();
49	    final Token.Doctype doctypePending = new Token.Doctype(); // doctype building up
50	    final Token.Comment commentPending = new Token.Comment(); // comment building up
51	    final Token.XmlDecl xmlDeclPending; // xml decl building up
52	    @Nullable private String lastStartTag; // the last start tag emitted, to test appropriate end tag
53	
54	    private int markupStartPos, charStartPos = 0; // reader pos at the start of markup / characters. markup updated on state transition, char on token emit.
55	
56	    Tokeniser(TreeBuilder treeBuilder) {
57	        this.treeBuilder = treeBuilder;
58	        syntax = treeBuilder instanceof XmlTreeBuilder ? Document.OutputSettings.Syntax.xml : Document.OutputSettings.Syntax.html;
59	        tagPending = startPending  = new Token.StartTag(treeBuilder);
60	        endPending = new Token.EndTag(treeBuilder);
61	        xmlDeclPending = new Token.XmlDecl(treeBuilder);
62	        this.reader = treeBuilder.reader;
63	        this.errors = treeBuilder.parser.getErrors();
64	    }
65	
66	    Token read() {
67	        if (ignoreLeadingLf && !isEmitPending && (reader.matches('\r') || reader.matches('\n'))) {
68	            if (reader.consume() == '\r') reader.matchConsume("\n");
69	            charStartPos = reader.pos();
70	            ignoreLeadingLf = false;
71	        }
72	        while (!isEmitPending) {
73	            state.read(this, reader);
74	        }
75	
76	        // if emit is pending, a non-character token was found: return any chars in buffer, and leave token for next read:
77	        if (charPending.data.hasData()) {
78	            return charPending;
79	        } else {
80	            isEmitPending = false;
81	            assert emitPending != null;
82	            return emitPending;
83	        }
84	    }
85	
86	    void emit(Token token) {
87	        ignoreLeadingLf = false;
88	        Validate.isFalse(isEmitPending);
89	
90	        emitPending = token;
91	        isEmitPending = true;
92	        token.startPos(markupStartPos);
93	        token.endPos(reader.pos());
94	        charStartPos = reader.pos(); // update char start when we complete a token emit
95	
96	        if (token.type == Token.TokenType.StartTag) {
97	            Token.StartTag startTag = (Token.StartTag) token;
98	            lastStartTag = startTag.name();
99	        } else if (token.type == Token.TokenType.EndTag) {
100	            Token.EndTag endTag = (Token.EndTag) token;
101	            if (endTag.hasAttributes())
102	                error("Attributes incorrectly present on end tag [/%s]", endTag.normalName());
103	        }
104	    }
105	
106	    /** Buffers text for the next character token. */
107	    void emit(final String str) {
108	        if (str.isEmpty()) return;
109	        if (ignoreLeadingLf) {
110	            ignoreLeadingLf = false;
111	            // literal newlines were consumed before tokenization; this LF came from a reference
112	            if (str.equals("\n")) {
113	                charStartPos = reader.pos();
114	                return;
115	            }
116	        }
117	        // buffer strings up until last string token found, to emit only one token for a run of character refs etc.
118	        // does not set isEmitPending; read checks that
119	        // todo move "<" to '<'...
120	        // bulk literal runs stop at null; decoded references are handled separately
121	        charPending.data.append(str);
122	        charPending.startPos(charStartPos);
123	        charPending.endPos(reader.pos());
124	    }
125	
126	    /** Buffers a character for the next character token. */
127	    void emit(char c) {
128	        ignoreLeadingLf = false;
129	        charPending.data.append(c);
130	        if (c == TokeniserState.nullChar) charPending.hasNull = true;
131	        charPending.startPos(charStartPos);
132	        charPending.endPos(reader.pos());
133	    }
134	
135	    /** Buffers a decoded character reference. */
136	    void emit(int[] codepoints) {
137	        if (codepoints[0] == 0) charPending.hasNull = true; // only numeric references can produce null
138	        emit(new String(codepoints, 0, codepoints.length));
139	    }
140	
141	    /** Skips the next character if it is a newline. */
142	    void ignoreLeadingLf() {
143	        ignoreLeadingLf = true;
144	    }
145	
146	    void transition(TokeniserState newState) {
147	        // track markup position on state transitions
148	        if (newState == TokeniserState.TagOpen)
149	            markupStartPos = reader.pos();
150	
151	        this.state = newState;
152	    }
153	
154	    void advanceTransition(TokeniserState newState) {
155	        transition(newState);
156	        reader.advance();
157	    }
158	
159	    final private int[] codepointHolder = new int[1]; // holder to not have to keep creating arrays
160	    final private int[] multipointHolder = new int[2];
161	
162	    /** Tries to consume a character reference, and returns: null if nothing, int[1], or int[2]. */
163	    int @Nullable [] consumeCharacterReference(@Nullable Character additionalAllowedCharacter, boolean inAttribute) {
164	        if (reader.isEmpty())
165	            return null;
166	        if (additionalAllowedCharacter != null && additionalAllowedCharacter == reader.current())
167	            return null;
168	        if (reader.matchesAnySorted(notCharRefCharsSorted))
169	            return null;
170	
171	        final int[] codeRef = codepointHolder;
172	        reader.mark();
173	        if (reader.matchConsume("#")) { // numbered
174	            boolean isHexMode = reader.matchConsumeIgnoreCase("X");
175	            String numRef = isHexMode ? reader.consumeHexSequence() : reader.consumeDigitSequence();
176	            if (numRef.isEmpty()) { // didn't match anything
177	                characterReferenceError("numeric reference with no numerals");
178	                reader.rewindToMark();
179	                return null;
180	            }
181	
182	            reader.unmark();
183	            if (!reader.matchConsume(";"))
184	                characterReferenceError("missing semicolon on [&#%s]", numRef); // missing semi
185	            int charval = -1;
186	            try {
187	                int base = isHexMode ? 16 : 10;
188	                charval = Integer.valueOf(numRef, base);
189	            } catch (NumberFormatException ignored) {
190	                // skip
191	            }
192	            // todo: check for extra illegal unicode points as parse errors - described https://html.spec.whatwg.org/multipage/syntax.html#character-references and in Infra
193	            // The numeric character reference forms described above are allowed to reference any code point excluding U+000D CR, noncharacters, and controls other than ASCII whitespace.
194	            if (charval == -1 || charval > 0x10FFFF || (charval == 0 && syntax == Document.OutputSettings.Syntax.html)) {
195	                characterReferenceError("character [%s] outside of valid range", charval);
196	                codeRef[0] = replacementChar;
197	            } else {
198	                // fix illegal unicode characters to match browser behavior
199	                if (charval >= win1252ExtensionsStart && charval < win1252ExtensionsStart + win1252Extensions.length) {
200	                    characterReferenceError("character [%s] is not a valid unicode code point", charval);
201	                    charval = win1252Extensions[charval - win1252ExtensionsStart];
202	                }
203	
204	                // todo: implement number replacement table
205	                // todo: check for extra illegal unicode points as parse errors
206	                codeRef[0] = charval;
207	            }
208	            return codeRef;
209	        } else { // named
210	            // get as many letters as possible, and look for matching entities.
211	            String nameRef = reader.consumeLetterThenDigitSequence();
212	            boolean looksLegit = reader.matches(';');
213	            // found if a base named entity without a ;, or an extended entity with the ;.
214	            boolean found = (Entities.isBaseNamedEntity(nameRef) || (Entities.isNamedEntity(nameRef) && looksLegit));
215	
216	            if (!found) {
217	                reader.rewindToMark();
218	                if (looksLegit) // named with semicolon
219	                    characterReferenceError("invalid named reference [%s]", nameRef);
220	                if (inAttribute) return null;
221	                // check if there's a base prefix match; consume and use that if so
222	                String prefix = Entities.findPrefix(nameRef);
223	                if (prefix.isEmpty()) return null;
224	                reader.matchConsume(prefix);
225	                nameRef = prefix;
226	            }
227	            if (inAttribute && (reader.matchesAsciiAlpha() || reader.matchesDigit() || reader.matchesAny('=', '-', '_'))) {
228	                // don't want that to match
229	                reader.rewindToMark();
230	                return null;
231	            }
232	
233	            reader.unmark();
234	            if (!reader.matchConsume(";"))
235	                characterReferenceError("missing semicolon on [&%s]", nameRef); // missing semi
236	            int numChars = Entities.codepointsForName(nameRef, multipointHolder);
237	            if (numChars == 1) {
238	                codeRef[0] = multipointHolder[0];
239	                return codeRef;
240	            } else if (numChars ==2) {
241	                return multipointHolder;
242	            } else {
243	                Validate.fail("Unexpected characters returned for " + nameRef);
244	                return multipointHolder;
245	            }
246	        }
247	    }
248	
249	    Token.Tag createTagPending(boolean start) {
250	        tagPending = start ? startPending.reset() : endPending.reset();
251	        return tagPending;
252	    }
253	
254	    Token.XmlDecl createXmlDeclPending(boolean isDeclaration) {
255	        Token.XmlDecl decl = xmlDeclPending.reset();
256	        decl.isDeclaration = isDeclaration;
257	        tagPending = decl;
258	        return decl;
259	    }
260	
261	    void emitTagPending() {
262	        tagPending.finaliseTag();
263	        emit(tagPending);
264	    }
265	
266	    void createCommentPending() {
267	        commentPending.reset();
268	    }
269	
270	    void emitCommentPending() {
271	        emit(commentPending);
272	    }
273	
274	    void createBogusCommentPending() {
275	        commentPending.reset();
276	        commentPending.bogus = true;
277	    }
278	
279	    void createDoctypePending() {
280	        doctypePending.reset();
281	    }
282	
283	    void emitDoctypePending() {
284	        emit(doctypePending);
285	    }
286	
287	    void createTempBuffer() {
288	        dataBuffer.reset();
289	    }
290	
291	    /** Test if CDATA sections are allowed at the adjusted current node. */
292	    boolean isCdataAllowed() {
293	        return syntax == Document.OutputSettings.Syntax.xml
294	            || (treeBuilder.hasCurrentElement() && !Parser.NamespaceHtml.equals(treeBuilder.currentElement().tag().namespace()));
295	    }
296	
297	    /** Test if the pending end tag matches the last emitted start tag. */
298	    boolean isAppropriateEndTagToken() {
299	        return lastStartTag != null && tagPending.name().equalsIgnoreCase(lastStartTag);
300	    }
301	
302	    /** Test if appending the character would keep the pending end tag a prefix of the expected name. */
303	    boolean isAppropriateEndTagPrefix(char next) {
304	        if (lastStartTag == null) return false;
305	
306	        String candidate = tagPending.normalName();
307	        int length = candidate.length();
308	        return length < lastStartTag.length()
309	            && lastStartTag.regionMatches(true, 0, candidate, 0, length)
310	            && lastStartTag.charAt(length) == next;
311	    }
312	
313	    void error(TokeniserState state) {
314	        if (errors.canAddError())
315	            errors.add(new ParseError(reader, "Unexpected character '%s' in input state [%s]", reader.current(), state));
316	    }
317	
318	    void eofError(TokeniserState state) {
319	        if (errors.canAddError())
320	            errors.add(new ParseError(reader, "Unexpectedly reached end of file (EOF) in input state [%s]", state));
321	    }
322	
323	    private void characterReferenceError(String message, Object... args) {
324	        if (errors.canAddError())
325	            errors.add(new ParseError(reader, String.format("Invalid character reference: " + message, args)));
326	    }
327	
328	    void error(String errorMsg) {
329	        if (errors.canAddError())
330	            errors.add(new ParseError(reader, errorMsg));
331	    }
332	
333	    void error(String errorMsg, Object... args) {
334	        if (errors.canAddError())
335	            errors.add(new ParseError(reader, errorMsg, args));
336	    }
337	
338	    /**
339	     * Utility method to consume reader and unescape entities found within.
340	     * @param inAttribute if the text to be unescaped is in an attribute
341	     * @return unescaped string from reader
342	     */
343	    String unescapeEntities(boolean inAttribute) {
344	        StringBuilder builder = StringUtil.borrowBuilder();
345	        while (!reader.isEmpty()) {
346	            builder.append(reader.consumeTo('&'));
347	            if (reader.matches('&')) {
348	                reader.consume();
349	                int[] c = consumeCharacterReference(null, inAttribute);
350	                if (c == null || c.length==0)
351	                    builder.append('&');
352	                else {
353	                    builder.appendCodePoint(c[0]);
354	                    if (c.length == 2)
355	                        builder.appendCodePoint(c[1]);
356	                }
357	
358	            }
359	        }
360	        return StringUtil.releaseBuilder(builder);
361	    }
362	}
