        Document d = Jsoup.parse(html);
        String out = d.html();
        String out2 = Jsoup.parse(out).html();
        System.out.println("--- " + label + "\n" + out.replace("\n","\\n") + (out.equals(out2) ? "" : "\n  RT-DIFF: " + out2.replace("\n","\\n")));
    }
    public static void main(String[] a) {
        t("siblings after title", "<title>t</title><p a=1 b=\"two\">x</p><div id=y>z</div>");
        t("siblings after textarea", "<textarea>t</textarea><p a=1>x</p><span>s</span>");
        t("script end with attr", "<script>a</script foo=bar><p>x</p>");
        t("script end selfclose", "<script>a</script/><p>x</p>");
        t("script end eof", "<script>a</script");
        t("script end other", "<script>a</scrip><p>x</p>");
        t("style end other", "<style>a</sty><p>x</p>");
        t("refs chain", "<title>&#65;&#x42;&amp;&#xG;&#67</title>");
        t("ref adj lt", "<title>&#65<&#66;</title>");
        t("ws preserved", "<title>  a   b\n c\t</title>");
        // buffer boundary: >32KB rcdata then a charref
        StringBuilder sb = new StringBuilder("<title>");
        for (int i = 0; i < 33000; i++) sb.append('x');
        sb.append("&#65;&#xD800;tail</title><p>after</p>");
        Document d = Jsoup.parse(sb.toString());
        String title = d.title();
        System.out.println("--- buffer boundary: len=" + title.length() + " ends=" + title.substring(title.length()-8));
        // ref split right at boundary
        StringBuilder sb2 = new StringBuilder("<title>");
        for (int i = 0; i < 32760; i++) sb2.append('y');
        sb2.append("&#x41;z</title>");
        String t2 = Jsoup.parse(sb2.toString()).title();
        System.out.println("--- boundary ref: tail=" + t2.substring(t2.length()-3));
    }
}
