import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.parser.Parser;

public class Final {
    static int fails = 0;
    static void check(String label, Object actual, Object expected) {
        boolean ok = actual.equals(expected);
        if (!ok) fails++;
        System.out.println((ok ? "PASS " : "FAIL ") + label + (ok ? "" : " expected=<" + expected + "> actual=<" + actual + ">"));
    }
    public static void main(String[] a) {
        // RCDATA: tag-like content is text
        check("title start tag as text", Jsoup.parse("<title>a<b>c</title>").title(), "a<b>c");
        check("title attr-like as text", Jsoup.parse("<title>a<b c=d>e</title>").title(), "a<b c=d>e");
        check("title stray lt", Jsoup.parse("<title>a < b</title>").title(), "a < b");
        check("textarea tag as text", Jsoup.parse("<textarea><img src=x></textarea>").text(), "<img src=x>");
        // case-insensitive end tag
        check("mixed case end", Jsoup.parse("<title><p>Foo</TiTLE>").title(), "<p>Foo");
        check("textarea mixed case", Jsoup.parse("<textarea><img src=x></TeXtArEa>").text(), "<img src=x>");
        // wrong-name end tag stays text
        check("wrong end tag", Jsoup.parse("<title>hi</titled><p>x</p>").title(), "hi</titled><p>x</p>");
        // siblings after end tag
        Document d = Jsoup.parse("<title>t</title><p a=1 b=\"two\">x</p><div id=y>z</div>");
        check("sibling order", d.body().html(), "<p a=\"1\" b=\"two\">x</p>\n<div id=\"y\">z</div>");
        // unclosed -> to EOF, no exception, no phantom nodes
        Document u = Jsoup.parse("<textarea>foo<p>bar");
        check("unclosed textarea", u.select("textarea").first().text(), "foo<p>bar");
        check("no phantom p", u.select("p").size(), 0);
        // numeric refs
        check("dec", Jsoup.parse("<title>&#65;</title>").title(), "A");
        check("hex lower x", Jsoup.parse("<title>&#x41;</title>").title(), "A");
        check("hex upper X", Jsoup.parse("<title>&#X41;</title>").title(), "A");
        check("no semicolon", Jsoup.parse("<title>&#65</title>").title(), "A");
        check("hex no semicolon", Jsoup.parse("<title>&#x41</title>").title(), "A");
        // zero / surrogate / out-of-range -> FFFD, following chars kept
        check("zero", Jsoup.parse("<title>a&#0;b</title>").title(), "a�b");
        check("surrogate hex", Jsoup.parse("<title>a&#xD800;b</title>").title(), "a�b");
        check("surrogate dec", Jsoup.parse("<title>a&#55296;b</title>").title(), "a�b");
        check("surrogate no semi", Jsoup.parse("<title>a&#xD800b</title>").title(), "a�b");
        check("oob", Jsoup.parse("<title>a&#x110000;b</title>").title(), "a�b");
        check("oob dec", Jsoup.parse("<title>a&#1114112;b</title>").title(), "a�b");
        check("valid below surrogates", Jsoup.parse("<title>&#xD7FF;</title>").title(), "퟿");
        check("valid above surrogates", Jsoup.parse("<title>&#xE000;</title>").title(), "");
        check("supplementary ok", Jsoup.parse("<title>&#x1F4AF;</title>").title(), "💯");
        // invalid refs preserved
        check("no digits", Jsoup.parse("<title>a&#;b</title>").title(), "a&#;b");
        check("no digits hex", Jsoup.parse("<title>a&#x;b</title>").title(), "a&#x;b");
        check("unknown named", Jsoup.parse("<title>a&nope;b</title>").title(), "a&nope;b");
        check("chain", Jsoup.parse("<title>&#65;&#xG;&#66</title>").title(), "A&#xG;B");
        // adjacency
        check("ref adj newline", Jsoup.parse("<title>a&#10;b</title>").title(), "a\nb");
        check("ref adj entity", Jsoup.parse("<title>&amp;&#65;</title>").title(), "&A");
        check("ref decodes lt as text", Jsoup.parse("<title>&#60;p&#62;</title>").title(), "<p>");
        check("ws preserved", Jsoup.parse("<title>  a   b\n c\t</title>").title(), "  a   b\n c\t");
        // script/style rawtext
        check("script no decode", Jsoup.parse("<script>a&amp;b&#65;</script>").select("script").first().data(), "a&amp;b&#65;");
        check("script no child nodes", Jsoup.parse("<script><b>x</b></script>").select("script").first().childNodeSize(), 1);
        check("style raw", Jsoup.parse("<style>a &amp; <b> {}</style>").select("style").first().data(), "a &amp; <b> {}");
        check("script unclosed to eof", Jsoup.parse("<script>var a = 1 < 2;").select("script").first().data(), "var a = 1 < 2;");
        // repeat parse & round-trip stability
        String[] inputs = {
            "<title>a<b>&#xD800;c</title><p id=x>t</p>",
            "<textarea>&#65;&amp;<b></textarea><div>y</div>",
            "<script><!--<script>x</script>--></script><p>z</p>",
            "<style>a{b:c}</style><span>s</span>",
        };
        for (String in : inputs) {
            String h1 = Jsoup.parse(in).html();
            String h1b = Jsoup.parse(in).html();
            String h2 = Jsoup.parse(h1).html();
            check("idempotent " + in.substring(0, 20), h1.equals(h1b) && h1.equals(h2), true);
        }
        // named entities & normal behavior unchanged
        check("named entity", Jsoup.parse("<p>&amp;&lt;&gt;&copy;</p>").text(), "&<>©");
        check("tag fix", Jsoup.parse("<b>bold<i>both</b>italic</i>").body().html(), "<b>bold<i>both</i></b><i>italic</i>");
        System.out.println(fails == 0 ? "ALL PASS" : fails + " FAILURES");
    }
}
