import org.jsoup.Jsoup;
import org.jsoup.nodes.*;

public class Verify {
    public static void main(String[] a) {
        // raw text node content, not the normalizing title() accessor
        Document d1 = Jsoup.parse("<title>a&#10;b</title>");
        System.out.println("ref adj newline: <" + ((TextNode) d1.selectFirst("title").childNode(0)).getWholeText().replace("\n","\\n") + ">");
        Document d2 = Jsoup.parse("<title>  a   b\n c\t</title>");
        System.out.println("ws preserved: <" + ((TextNode) d2.selectFirst("title").childNode(0)).getWholeText().replace("\n","\\n").replace("\t","\\t") + ">");
        // &#xD800b -> b is a hex digit, 0xD800B is a valid (unassigned) scalar value, not a surrogate
        System.out.println("0xD800B valid scalar: " + (0xD800B <= 0x10FFFF && !(0xD800B >= 0xD800 && 0xD800B <= 0xDFFF)));
        // surrogate without semicolon where terminator is non-hex
        Document d3 = Jsoup.parse("<title>a&#xD800;b</title>");
        System.out.println("surrogate no-semi-impossible note; with semi: <" + d3.selectFirst("title").text() + ">");
        Document d4 = Jsoup.parse("<title>a&#xD800g</title>"); // g not hex -> digits "D800", then 'g'
        System.out.println("surrogate then non-hex char: <" + ((TextNode) d4.selectFirst("title").childNode(0)).getWholeText() + ">");
    }
}
